'use strict';
document.querySelector('.paperstage').insertAdjacentHTML('beforebegin','<div class="studio-toolbar"><button id="speechTools">Captions & lip-sync</button><button id="sequenceTools">Sequences</button><button id="recoveryTools">Recovery & media</button><span id="studioTaskStatus"></span></div>');
document.body.insertAdjacentHTML('beforeend',`<dialog id="sequenceDialog"><div class="tool-heading"><div><div class="eyebrow">REUSABLE STORIES</div><h2>Your animated sequences</h2></div><button id="closeSequences">Close</button></div><p class="note">Save scenes with their characters, animation, captions and audio. Insert a sequence at the end of any project.</p><div class="tool-row"><input id="sequenceName" placeholder="e.g. Channel intro" maxlength="80" aria-label="Sequence name"><select id="sequenceScope"><option value="scene">Current scene</option><option value="project">Entire project</option></select><button id="saveSequence" class="primary">Save sequence</button></div><div id="sequenceList"></div></dialog><dialog id="recoveryDialog"><div class="tool-heading"><div><div class="eyebrow">PROJECT SAFETY</div><h2>Recovery & media health</h2></div><button id="closeRecovery">Close</button></div><p class="note">Automatic recovery snapshots are taken every minute when edits change. Media is shared between snapshots to save space. The latest 10 snapshots are kept.</p><div class="tool-row"><button id="backupNow" class="primary">Create recovery point</button><button id="checkMedia">Check project media</button><span id="recoveryStatus"></span></div><div id="mediaHealth"></div><h3>Recovery history</h3><div id="recoveryList"></div><input id="replaceMedia" type="file" hidden></dialog>`);
async function workspaceValue(key){return assetRecords('readonly',s=>s.get(key))}
async function workspacePut(key,value){return assetRecords('readwrite',s=>s.put(value,key))}
function buildSequence(scope,name){const all=scope==='project',scenes=structuredClone(all?project.scenes:[current()]),start=all?0:sceneOffset(),end=all?totalDuration():start+current().duration;const audio=tracks().filter(c=>audioEnd(c)>start&&c.start<end).map(c=>{const copy=structuredClone(c),left=Math.max(start,c.start),right=Math.min(end,audioEnd(c));copy.start=left-start;copy.offset+=(left-c.start)*(c.rate||1);copy.duration=right-left;copy.fadeIn=Math.min(copy.fadeIn||0,copy.duration);copy.fadeOut=Math.min(copy.fadeOut||0,copy.duration);return copy});return{id:uid(),name,scenes,audio,cast:structuredClone(project.cast),savedAt:Date.now()}}
async function insertSequence(entry){if(project.scenes.length+entry.scenes.length>=100)return toast('Keep fewer than 100 scenes per project.');stop();const offset=totalDuration(),copy=structuredClone(entry),ids=new Map(),sceneIds=new Map();for(const s of copy.scenes){const oldScene=s.id;s.id=uid();sceneIds.set(oldScene,s.id);for(const o of s.objects){const old=o.id;o.id=uid();ids.set(old,o.id)}}const audioIds=new Map(copy.audio.map(c=>[c.id,uid()]));for(const c of copy.audio){c.id=audioIds.get(c.id);c.start+=offset;if(c.videoId)c.videoId=ids.get(c.videoId)||undefined}for(const s of copy.scenes)for(const o of s.objects){if(o.speechTrackId)o.speechTrackId=audioIds.get(o.speechTrackId)||undefined;for(const key of ['lookTargetId','pointTargetId'])if(o[key])o[key]=ids.get(o[key])||null;if(o.exitTransition?.toId)o.exitTransition.toId=ids.get(o.exitTransition.toId)||null}if(typeof remapStoryReferences==='function')remapStoryReferences(copy,ids,audioIds,sceneIds);const first=project.scenes.length;project.scenes.push(...copy.scenes);tracks().push(...copy.audio);for(const ch of copy.cast||[])if(!project.cast.some(c=>c.id===ch.id))project.cast.push(ch);sceneIndex=first;time=0;selected=null;selectedAudio=null;save();renderCast();render();await hydrateAudio();$('sequenceDialog').close();toast(entry.name+' inserted with animation and audio.')}
async function renderSequences(){const list=await workspaceValue('sequences')||[];$('sequenceList').replaceChildren();if(!list.length)$('sequenceList').innerHTML='<p class="note">Your saved intros, explanations and outros will appear here.</p>';for(const entry of list){const row=document.createElement('div');row.className='workspace-entry';const text=document.createElement('div');const name=document.createElement('strong');name.textContent=entry.name;const meta=document.createElement('small');meta.textContent=entry.scenes.length+' scenes · '+entry.scenes.reduce((n,s)=>n+s.duration,0).toFixed(1)+' s · '+entry.audio.length+' audio clips';text.append(name,meta);const add=document.createElement('button');add.textContent='Insert';add.onclick=()=>insertSequence(entry).catch(e=>toast(e.message));const del=document.createElement('button');del.textContent='Remove';del.onclick=async()=>{await workspacePut('sequences',(await workspaceValue('sequences')||[]).filter(e=>e.id!==entry.id));renderSequences()};row.append(text,add,del);$('sequenceList').append(row)}}
$('sequenceTools').onclick=()=>{stop();renderSequences().catch(()=>toast('Could not load sequences.'));$('sequenceDialog').showModal()};$('closeSequences').onclick=()=>$('sequenceDialog').close();$('saveSequence').onclick=async()=>{const name=$('sequenceName').value.trim()||current().name;try{const list=await workspaceValue('sequences')||[];if(list.length>=30)return toast('Remove a saved sequence before adding another.');list.push(buildSequence($('sequenceScope').value,name));await workspacePut('sequences',list);renderSequences();toast('Sequence saved with its media.')}catch{toast('Could not save sequence. Save a project backup.')}};
let recoveryDirty=false,recoveryQueue=Promise.resolve(),lastRecoverySignature='',mediaReplacement=null;
const recoverySave=save;save=function(){recoveryDirty=true;recoverySave()};
async function assetKey(value){const bytes=new TextEncoder().encode(value),hash=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('')}
function makeRecovery(reason='Automatic recovery'){const captured=structuredClone(project);const task=async()=>{const signature=JSON.stringify(captured);if(signature===lastRecoverySignature&&reason==='Automatic recovery')return;const list=await workspaceValue('recoveries')||[],assets=await workspaceValue('recoveryAssets')||{},urls=new Set();JSON.stringify(captured,(_key,value)=>{if(typeof value==='string'&&value.startsWith('data:'))urls.add(value);return value});const map=new Map();for(const url of urls){const key=await assetKey(url);map.set(url,key);assets[key]=url}const packed=JSON.parse(JSON.stringify(captured,(_key,value)=>map.has(value)?'@asset:'+map.get(value):value));list.unshift({id:uid(),at:Date.now(),reason,title:captured.title,data:packed});list.splice(10);const used=new Set();for(const entry of list)JSON.stringify(entry.data,(_key,value)=>{if(typeof value==='string'&&value.startsWith('@asset:'))used.add(value.slice(7));return value});for(const key of Object.keys(assets))if(!used.has(key))delete assets[key];const db=await database();await new Promise((resolve,reject)=>{const tx=db.transaction('workspace','readwrite'),store=tx.objectStore('workspace');store.put(list,'recoveries');store.put(assets,'recoveryAssets');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});lastRecoverySignature=signature;recoveryDirty=JSON.stringify(project)!==signature;return list[0]};recoveryQueue=recoveryQueue.catch(()=>{}).then(task);return recoveryQueue}
async function restoreRecovery(entry){const assets=await workspaceValue('recoveryAssets')||{};let missing=false;const restored=JSON.parse(JSON.stringify(entry.data),(_key,value)=>{if(typeof value==='string'&&value.startsWith('@asset:')){if(!assets[value.slice(7)])missing=true;return assets[value.slice(7)]}return value});if(missing||!valid(restored))throw Error('This recovery point is incomplete. Use a project backup.');await makeRecovery('Before restoring a recovery');loadProject(restored);$('recoveryDialog').close();toast('Recovery restored. Your previous workspace is also backed up.')}
async function renderRecoveries(){const list=await workspaceValue('recoveries')||[];$('recoveryList').replaceChildren();if(!list.length)$('recoveryList').innerHTML='<p class="note">No recovery points yet. Create one now or keep editing to start automatic backups.</p>';for(const entry of list){const row=document.createElement('div');row.className='workspace-entry';const text=document.createElement('div');const title=document.createElement('strong');title.textContent=entry.title;const meta=document.createElement('small');meta.textContent=new Intl.DateTimeFormat('en-ZA',{dateStyle:'medium',timeStyle:'short',timeZone:'Africa/Johannesburg'}).format(entry.at)+' · '+entry.reason;text.append(title,meta);const restore=document.createElement('button');restore.textContent='Restore';restore.onclick=()=>restoreRecovery(entry).catch(e=>toast(e.message));const backup=document.createElement('button');backup.textContent='Download';backup.onclick=async()=>{const assets=await workspaceValue('recoveryAssets')||{},p=JSON.parse(JSON.stringify(entry.data),(_k,v)=>typeof v==='string'&&v.startsWith('@asset:')?assets[v.slice(7)]:v);download(new Blob([JSON.stringify(p,null,2)],{type:'application/json'}),'elleson-recovery.json')};row.append(text,restore,backup);$('recoveryList').append(row)}}
$('recoveryTools').onclick=()=>{stop();renderRecoveries().catch(()=>toast('Could not read recovery history.'));$('recoveryDialog').showModal()};$('closeRecovery').onclick=()=>$('recoveryDialog').close();$('backupNow').onclick=async()=>{try{$('recoveryStatus').textContent='Saving recovery…';await makeRecovery('Manual recovery');await renderRecoveries();$('recoveryStatus').textContent='Recovery point saved.'}catch{$('recoveryStatus').textContent='Recovery failed. Save a project backup.'}};
setInterval(()=>{if(recoveryDirty&&!playing&&!recording&&!audioBusy)makeRecovery().catch(()=>{$('saveStatus').textContent='Recovery failed · download backup'})},60000);
const recoveryLoad=loadProject;loadProject=function(p){if(historyStack.length>1)makeRecovery('Before switching projects').catch(()=>{});recoveryLoad(p)};
async function inspectProjectMedia(){const issues=[],assets=[];for(const s of project.scenes)for(const o of s.objects)if(o.type==='image'||o.type==='video')assets.push({kind:o.type,name:o.name,scene:s,object:o});for(const c of tracks())assets.push({kind:'audio',name:c.name,audio:c});for(const s of project.scenes)if(s.backgroundImage)assets.push({kind:'background',name:s.name+' background',scene:s});for(const asset of assets){try{if(asset.kind==='audio'){if(!audioBuffers.has(asset.audio.id))throw Error('Audio not decoded')}else if(asset.kind==='video')await mediaReady(videoFor(asset.object),'loadedmetadata');else await imageReady(asset.kind==='background'?asset.scene.backgroundImage:asset.object.src)}catch{issues.push(asset)}}return{count:assets.length,issues}}
$('checkMedia').onclick=async()=>{$('mediaHealth').textContent='Checking imported media…';try{const {count,issues}=await inspectProjectMedia();$('mediaHealth').replaceChildren();const summary=document.createElement('p');summary.className='note';summary.textContent=issues.length?issues.length+' files need attention.':count+' media assets checked. All are available.';$('mediaHealth').append(summary);for(const issue of issues){const row=document.createElement('div');row.className='workspace-entry';const text=document.createElement('span');text.textContent=issue.name;const replace=document.createElement('button');replace.textContent='Replace file';replace.onclick=()=>{mediaReplacement=issue;$('replaceMedia').accept=issue.kind==='audio'?'audio/*':issue.kind==='video'?'video/*':'image/*';$('replaceMedia').click()};row.append(text,replace);$('mediaHealth').append(row)}}catch{$('mediaHealth').textContent='Media check failed. Save a project backup before continuing.'}};
$('replaceMedia').onchange=async e=>{const f=e.target.files[0],item=mediaReplacement;e.target.value='';if(!f||!item)return;stop();try{const src=await dataURL(f);if(item.kind==='audio'){const buffer=await decodeFile(f),c=item.audio;c.src=src;c.sourceDuration=buffer.duration;c.offset=0;c.duration=Math.min(c.duration,buffer.duration);delete c.videoId;delete c.normalization;delete c.beats;delete c.words;delete c.mouthCues;audioBuffers.set(c.id,buffer)}else if(item.kind==='video'){const o=item.object,video=document.createElement('video');video.muted=true;video.src=src;await mediaReady(video);o.src=src;o.sourceDuration=video.duration;o.sourceOffset=0;o.out=Math.min(clipEnd(o,item.scene),clipStart(o)+video.duration/(o.speed||1));for(const c of tracks().filter(c=>c.videoId===o.id)){delete c.videoId}videoMedia.set(o.id,{src,video})}else{await imageReady(src);if(item.kind==='background')item.scene.backgroundImage=src;else item.object.src=src}save();render();$('mediaHealth').textContent='File replaced. Run the media check again to verify the project.'}catch(e){toast(e.message||'This replacement file could not be opened.')}};
try{const interrupted=localStorage.getItem('elleson-editor-session')==='open';localStorage.setItem('elleson-editor-session','open');if(interrupted){const review=document.createElement('button');review.id='reviewRecoveredWork';review.className='recovery-notice';review.textContent='Review recovered work';review.title='The previous session did not close normally. Your autosaved workspace will be restored; review recovery history here.';review.onclick=()=>{$('recoveryTools').click();review.remove()};document.querySelector('.studio-toolbar').append(review)}}catch{}
window.addEventListener('beforeunload',()=>{try{localStorage.setItem('elleson-editor-session','closed')}catch{}});
